const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const env = (k) => String($env[k] ?? '').trim();
const e = $input.first().json;
const ex = e.execution || {};
const err = ex.error || e.trigger?.error || {};
const node = err.node?.name || ex.lastNodeExecuted || 'unknown';
const text = [
  `<b>Workflow failed: ${esc(e.workflow?.name || 'unknown')}</b>`,
  `Node: ${esc(node)}`,
  `Error: ${esc(String(err.message || 'no message').slice(0, 500))}`,
  err.description ? `Details: ${esc(String(err.description).slice(0, 300))}` : '',
  ex.url ? `Execution: ${esc(ex.url)}` : '',
  ex.mode ? `Mode: ${esc(ex.mode)}` : '',
].filter(Boolean).join('\n');
return [{ json: { chat_id: env('LEADS_OPS_CHAT_ID'), text } }];
